<script setup>
import {computed,onBeforeUnmount,ref,watch} from 'vue';
import {ElMessage} from 'element-plus';
import {uploadTeamAttachment,withImageToken} from '../../api/tools/imageCropper.js';
import {currentApiCacheScope} from '../../utils/api.js';
import {MOBILE_PHOTO_LIMIT,prepareMobilePhoto,validateMobilePhoto} from '../../utils/mobile-evidence.js';
const props=defineProps({modelValue:{type:Array,default:()=>[]},disabled:Boolean,label:{type:String,default:'照片凭证'}}),emit=defineEmits(['update:modelValue','state']);
const entries=ref([]),camera=ref(),album=ref();let disposed=false,version=0;
const busy=computed(()=>entries.value.some(r=>r.status==='uploading'));
function report(){emit('update:modelValue',entries.value.filter(r=>r.status==='done').map(r=>r.url));emit('state',{busy:busy.value,ready:entries.value.every(r=>r.status==='done')});}
async function upload(row){if(props.disabled)return;const token=version,scope=currentApiCacheScope();row.status='uploading';row.error='';report();try{const prepared=await prepareMobilePhoto(row.file);if(disposed||token!==version||scope!==currentApiCacheScope())return;const result=await uploadTeamAttachment(prepared);if(disposed||token!==version||scope!==currentApiCacheScope())return;if(!/^\/uploads\/team-attachments\/[^/?#]+$/.test(String(result?.url||'')))throw Error('上传回执无效，请重试');row.url=result.url;row.status='done';}catch(e){if(disposed||token!==version||scope!==currentApiCacheScope())return;row.status='error';row.error=e.message;}finally{if(!disposed&&token===version&&scope===currentApiCacheScope())report();}}
async function choose(event){const token=version;const files=[...(event.target.files||[])];event.target.value='';if(entries.value.length+files.length>MOBILE_PHOTO_LIMIT)return ElMessage.warning('每次最多6张照片，请分批选择');for(const file of files){if(disposed||token!==version)return;try{validateMobilePhoto(file);}catch(e){ElMessage.warning(e.message);continue;}const row={key:crypto.randomUUID(),name:file.name,file,preview:URL.createObjectURL(file),status:'pending',url:'',error:''};entries.value.push(row);await upload(entries.value[entries.value.length-1]);}}
function remove(row){if(props.disabled||row.status==='uploading')return;if(row.preview?.startsWith('blob:'))URL.revokeObjectURL(row.preview);entries.value=entries.value.filter(r=>r!==row);report();}
function reset(){++version;for(const r of entries.value)if(r.preview?.startsWith('blob:'))URL.revokeObjectURL(r.preview);entries.value=[];report();}
watch(()=>props.modelValue,urls=>{if(!entries.value.length&&urls?.length)entries.value=urls.map(url=>({key:url,url,status:'done',preview:withImageToken(url)}));},{immediate:true});
window.addEventListener('erp:auth-scope-changed',reset);onBeforeUnmount(()=>{disposed=true;++version;for(const r of entries.value)if(r.preview?.startsWith('blob:'))URL.revokeObjectURL(r.preview);window.removeEventListener('erp:auth-scope-changed',reset);});
</script>
<template><section class="mobile-evidence"><b>{{label}}（选填，最多6张）</b><div class="mobile-record-actions"><el-button :disabled="disabled||busy" @click="camera.click()">拍照</el-button><el-button :disabled="disabled||busy" @click="album.click()">从相册选择</el-button></div><input ref="camera" type="file" accept="image/*" capture="environment" hidden :disabled="disabled||busy" @change="choose"><input ref="album" type="file" accept="image/*" multiple hidden :disabled="disabled||busy" @change="choose"><div v-if="entries.length" class="evidence-grid"><article v-for="row in entries" :key="row.key"><el-image :src="row.preview" :preview-src-list="[row.preview]" preview-teleported fit="cover"/><small v-if="row.status==='uploading'">正在压缩上传…</small><small v-if="row.status==='error'" role="alert">{{row.error}}</small><el-button v-if="row.status==='error'" :disabled="disabled||busy" @click="upload(row)">重试上传</el-button><el-button :disabled="disabled||row.status==='uploading'" @click="remove(row)">移除</el-button></article></div></section></template>
<style scoped>.mobile-evidence{display:grid;gap:9px;font-size:13px}.evidence-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:8px}.evidence-grid article{display:grid;gap:6px;padding:8px;border:1px solid var(--el-border-color);border-radius:10px;min-width:0}.evidence-grid .el-image{width:100%;height:110px}.evidence-grid small{overflow-wrap:anywhere;color:var(--el-color-danger)}.evidence-grid .el-button{margin:0}</style>
